-- Security deposit ledger and tenant-damage maintenance workflow.
alter table public.maintenance_requests add constraint maintenance_id_org_unique unique(id,organization_id);
alter table public.maintenance_requests add column if not exists maintenance_cost_minor bigint not null default 0 check(maintenance_cost_minor>=0), add column if not exists tenant_damage boolean not null default false, add column if not exists responsible_lease_id uuid, add column if not exists deposit_deduction_minor bigint not null default 0 check(deposit_deduction_minor>=0), add constraint maintenance_responsible_lease_org_fk foreign key(responsible_lease_id,organization_id) references public.leases(id,organization_id) on delete restrict;
create table public.security_deposit_transactions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,lease_id uuid not null,tenant_id uuid not null,transaction_type text not null check(transaction_type in('received','damage_deduction','refund')),amount_minor bigint not null check(amount_minor>0),maintenance_request_id uuid,description text not null,recorded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(lease_id,organization_id) references public.leases(id,organization_id) on delete restrict,foreign key(tenant_id,organization_id) references public.tenants(id,organization_id) on delete restrict,foreign key(maintenance_request_id,organization_id) references public.maintenance_requests(id,organization_id) on delete restrict,unique(maintenance_request_id));
create index security_deposit_lease_created_idx on public.security_deposit_transactions(organization_id,lease_id,created_at desc);
alter table public.security_deposit_transactions enable row level security;
create policy security_deposit_member_select on public.security_deposit_transactions for select to authenticated using(private.is_org_member(organization_id));
create policy security_deposit_finance_insert on public.security_deposit_transactions for insert to authenticated with check(recorded_by=(select auth.uid()) and private.has_org_role(organization_id,array['owner','admin','manager','accountant']::public.organization_role[]));
grant select,insert on public.security_deposit_transactions to authenticated;
create or replace function private.enforce_security_deposit_ledger() returns trigger language plpgsql security definer set search_path='' as $$ declare v_lease public.leases%rowtype; v_received bigint; v_deductions bigint; v_refunds bigint; begin if tg_op<>'INSERT' then raise exception 'Security deposit ledger entries are immutable'; end if; select * into v_lease from public.leases where id=new.lease_id and organization_id=new.organization_id and tenant_id=new.tenant_id for update; if not found then raise exception 'Lease and tenant do not match'; end if; select coalesce(sum(amount_minor) filter(where transaction_type='received'),0),coalesce(sum(amount_minor) filter(where transaction_type='damage_deduction'),0),coalesce(sum(amount_minor) filter(where transaction_type='refund'),0) into v_received,v_deductions,v_refunds from public.security_deposit_transactions where lease_id=new.lease_id and organization_id=new.organization_id; if new.transaction_type='received' and v_received+new.amount_minor>v_lease.deposit_amount_minor then raise exception 'Deposit receipts cannot exceed agreed lease deposit'; elsif new.transaction_type='damage_deduction' and (new.maintenance_request_id is null or new.amount_minor>v_received-v_deductions-v_refunds) then raise exception 'Damage deduction requires maintenance evidence and available deposit'; elsif new.transaction_type='refund' and new.amount_minor>v_received-v_deductions-v_refunds then raise exception 'Refund exceeds remaining deposit balance'; end if; return new; end $$;
create trigger security_deposit_ledger_guard before insert or update or delete on public.security_deposit_transactions for each row execute function private.enforce_security_deposit_ledger();
create or replace function public.record_security_deposit_transaction(p_organization_id uuid,p_lease_id uuid,p_transaction_type text,p_amount_minor bigint,p_description text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_lease public.leases%rowtype; v_id uuid; begin if auth.uid() is null or not private.has_org_role(p_organization_id,array['owner','admin','manager','accountant']::public.organization_role[]) then raise exception 'Not authorised to manage security deposits'; end if; if p_transaction_type not in('received','refund') or p_amount_minor<=0 or length(trim(coalesce(p_description,'')))<3 then raise exception 'Enter valid deposit receipt or refund'; end if; select * into v_lease from public.leases where id=p_lease_id and organization_id=p_organization_id for update; if not found then raise exception 'Lease not found'; end if; insert into public.security_deposit_transactions(organization_id,lease_id,tenant_id,transaction_type,amount_minor,description,recorded_by) values(p_organization_id,p_lease_id,v_lease.tenant_id,p_transaction_type,p_amount_minor,trim(p_description),auth.uid()) returning id into v_id; return v_id; end $$;
revoke all on function public.record_security_deposit_transaction(uuid,uuid,text,bigint,text) from public,anon; grant execute on function public.record_security_deposit_transaction(uuid,uuid,text,bigint,text) to authenticated;
create or replace function public.record_maintenance_cost_and_deposit_deduction(p_organization_id uuid,p_request_id uuid,p_cost_minor bigint,p_tenant_damage boolean,p_lease_id uuid,p_deduction_minor bigint,p_description text) returns void language plpgsql security definer set search_path='' as $$ declare v_request public.maintenance_requests%rowtype; v_lease public.leases%rowtype; v_balance bigint; begin if auth.uid() is null or not private.has_org_role(p_organization_id,array['owner','admin','manager','accountant']::public.organization_role[]) then raise exception 'Not authorised'; end if; if p_cost_minor<0 or p_deduction_minor<0 or p_deduction_minor>p_cost_minor then raise exception 'Invalid amounts'; end if; select * into v_request from public.maintenance_requests where id=p_request_id and organization_id=p_organization_id for update; if not found then raise exception 'Maintenance request not found'; end if; if p_deduction_minor>0 then if not p_tenant_damage or p_lease_id is null or v_request.unit_id is null then raise exception 'Tenant damage, unit and responsible lease are required'; end if; select * into v_lease from public.leases where id=p_lease_id and organization_id=p_organization_id and unit_id=v_request.unit_id and start_date<=v_request.reported_at::date and(end_date is null or end_date>=v_request.reported_at::date) for update; if not found then raise exception 'Lease did not occupy this unit at the reported time'; end if; select coalesce(sum(case when transaction_type='received' then amount_minor else -amount_minor end),0) into v_balance from public.security_deposit_transactions where lease_id=p_lease_id and organization_id=p_organization_id; if p_deduction_minor>v_balance then raise exception 'Deduction exceeds deposit balance'; end if; insert into public.security_deposit_transactions(organization_id,lease_id,tenant_id,transaction_type,amount_minor,maintenance_request_id,description,recorded_by) values(p_organization_id,p_lease_id,v_lease.tenant_id,'damage_deduction',p_deduction_minor,p_request_id,coalesce(nullif(trim(p_description),''),'Documented tenant damage'),auth.uid()); end if; update public.maintenance_requests set maintenance_cost_minor=p_cost_minor,tenant_damage=p_tenant_damage,responsible_lease_id=case when p_deduction_minor>0 then p_lease_id else null end,deposit_deduction_minor=p_deduction_minor,updated_at=now() where id=p_request_id and organization_id=p_organization_id; end $$;
revoke all on function public.record_maintenance_cost_and_deposit_deduction(uuid,uuid,bigint,boolean,uuid,bigint,text) from public,anon; grant execute on function public.record_maintenance_cost_and_deposit_deduction(uuid,uuid,bigint,boolean,uuid,bigint,text) to authenticated;
